// Extractor Node: Regex Parser for VLESS, VMess, Hysteria2, Trojan, and MTProto
const rawHtml = $input.first().json.body || '';
const items = [];
const seen = new Set();

// 1. Regex Matchers
const uriRegex = /(?:vless|trojan|hysteria2|hy2|tuic):\/\/[^\s\r\n<>"']+/gi;
const vmessRegex = /vmess:\/\/[a-zA-Z0-9+/=_-]+/gi;
const mtprotoRegex = /(?:tg:\/\/proxy\?|https:\/\/t\.me\/proxy\?)[^\s\r\n<>"']+/gi;

const matchesUri = rawHtml.match(uriRegex) || [];
const matchesVmess = rawHtml.match(vmessRegex) || [];
const matchesProxy = rawHtml.match(mtprotoRegex) || [];

// Parse URI nodes
for (const uri of matchesUri) {
  const clean = uri.trim();
  if (!seen.has(clean)) {
    seen.add(clean);
    try {
      const url = new URL(clean);
      const protocol = url.protocol.replace(':', '').toLowerCase();
      const host = url.hostname;
      const port = parseInt(url.port || '443', 10);
      const remark = decodeURIComponent(url.hash.replace('#', '')) || 'نود پرسرعت ضد فیلتر';

      // Detect Operator
      let operator = 'all';
      const lowerRemark = (remark + ' ' + host).toLowerCase();
      if (lowerRemark.includes('mci') || lowerRemark.includes('همراه اول')) operator = 'mci';
      else if (lowerRemark.includes('irancell') || lowerRemark.includes('mtn') || lowerRemark.includes('ایرانسل') || protocol === 'hysteria2') operator = 'irancell';
      else if (lowerRemark.includes('rightel') || lowerRemark.includes('رایتل')) operator = 'rightel';
      else if (lowerRemark.includes('wifi') || lowerRemark.includes('مخابرات') || lowerRemark.includes('شاتل')) operator = 'wifi';

      items.push({
        type: 'v2ray',
        protocol,
        configString: clean,
        name: remark.slice(0, 40),
        host,
        port,
        operator,
        location: host.includes('.de') || remark.includes('آلمان') ? '🇩🇪 آلمان' : '🌍 سرور بین‌المللی',
        flag: host.includes('.de') || remark.includes('آلمان') ? '🇩🇪' : '⚡'
      });
    } catch(e) {}
  }
}

// Parse MTProto Proxies
for (const pUrl of matchesProxy) {
  const clean = pUrl.trim();
  if (!seen.has(clean)) {
    seen.add(clean);
    try {
      const url = new URL(clean.replace('tg://', 'https://'));
      const host = url.searchParams.get('server');
      const port = parseInt(url.searchParams.get('port') || '443', 10);
      const secret = url.searchParams.get('secret');

      if (host && secret) {
        items.push({
          type: 'mtproto',
          name: `⚡ پروکسی ضد فیلتر TLS (${host})`,
          host,
          port,
          secret,
          operator: 'all',
          location: '🇩🇪 آلمان - فرانکفورت',
          flag: '🇩🇪'
        });
      }
    } catch(e) {}
  }
}

return items.map(item => ({ json: item }));
